#include <iostream>
#include <memory>
#include <string>
using namespace std;

class Cat {
public:
    virtual string speak() const { return "……"; }
    virtual ~Cat() = default;
};

class FishCat : public Cat {
public:
    string speak() const override { return "小鱼干喵！"; }
};

class BallCat : public Cat {
public:
    string speak() const override { return "毛线球喵！"; }
};

unique_ptr<Cat> makeCat(int kind) {
    if (kind == 1) return make_unique<FishCat>();
    return make_unique<BallCat>();
}

int main() {
    int k = 0;
    for (int i = 0; i < {w}; i++) {
        cin >> k;
        auto cat = makeCat(k);
        cout << "第 " << i + 1 << " 只：" << cat->speak() << endl;
    }
    return 0;
}
